/bin/bash -lc "python - <<'PY'
import numpy as np
import mujoco
from sim import Sim, BIN_CENTER
from solve import Controller

sim=Sim(); sim.reset(); ctrl=Controller(sim)

cup0=sim.cup_position(); pregrasp=cup0+np.array([0,0,0.25]); grasp_z=cup0[2]+0.0584
bin_center=np.array(BIN_CENTER)

def dist(target):
    hp,_=ctrl.hand_pose();
    return float(np.linalg.norm(hp-target))

phase=0; phase_steps=0
for step in range(1500):
    cup=sim.cup_position()
    if phase==0:
        ctrl.goto(pregrasp, ctrl.gripper_open, quat=ctrl.hand_quat_des)
        if dist(pregrasp)<0.03:
            phase=1; phase_steps=0
    elif phase==1:
        g=cup.copy(); g[2]=grasp_z
        ctrl.goto(g, ctrl.gripper_open, quat=ctrl.hand_quat_des)
        if dist(g)<0.02 and phase_steps>40:
            phase=2; phase_steps=0
    elif phase==2:
        g=cup.copy(); g[2]=grasp_z
        ctrl.goto(g, ctrl.gripper_closed, quat=ctrl.hand_quat_des)
    sim.step(1)
    phase_steps+=1
    if step%200==0:
        hp,hm=ctrl.hand_pose();
        print('step',step,'phase',phase,'hand',hp,'cup',cup,'dist_pre',dist(pregrasp),'contact',sim.has_gripper_cup_contact())

print('final phase',phase,'hand',ctrl.hand_pose()[0],'cup',sim.cup_position())
PY"

